import React, { useState } from "react";
import { Column, StatusFilter, UserTypeFilter } from "@features/shared/types";

// export const ALL_EXTRA_COLUMNS = [
//   { key: "name", label: "Name" },
//   { key: "location", label: "Location" },
//   { key: "phone", label: "Phone" },
//   { key: "headline", label: "Headline" },
//   { key: "status", label: "Status" },
// ];

export const ALL_EXTRA_COLUMNS: Column[] = [
  {
    key: "location",
    label: "Location",
  },
  {
    key: "phone",
    label: "Phone",
  },
  {
    key: "professional_headline",
    label: "Headline",
  },
  {
    key: "created_at",
    label: "Joined",
  },
];

interface User {
  id: string;
  first_name: string | null;
  last_name: string | null;
  image_url: string | null;
  professional_headline: string | null;
  name: string;
}

interface ToolbarProps {
  searchTerm: string;
  onSearch: (value: string) => void;

  locationFilter: string;
  onLocationChange: (value: string) => void;
  locationOptions: { label: string; value: string }[];

  statusFilter: StatusFilter;
  onStatusChange: (value: StatusFilter) => void;

  userTypeFilter: UserTypeFilter;
  onUserTypeChange: (value: UserTypeFilter) => void;

  visibleCols: Set<string>;
  onToggleCol: (key: string) => void;

  users?: User[];
}

interface DropdownProps {
  value: string;
  options: { label: string; value: string }[];
  onChange: (value: string) => void;
  placeholder: string;
  isMobile?: boolean;
}

/* ------------------------------ Avatar ------------------------------ */

// const Avatar = ({ user }: { user: User }) => {
//   const initials =
//     `${user.first_name?.[0] || ""}${user.last_name?.[0] || ""}`.toUpperCase();

//   const fallbackAvatar = `https://ui-avatars.com/api/?name=${encodeURIComponent(
//     user.name || initials || "User"
//   )}&background=0F172A&color=fff`;

//   return (
//     <div
//       style={{
//         width: 40,
//         height: 40,
//         borderRadius: "50%",
//         overflow: "hidden",
//         background: "#E2E8F0",
//         display: "flex",
//         alignItems: "center",
//         justifyContent: "center",
//         flexShrink: 0,
//         position: "relative",
//       }}
//     >
//       <img
//         src={user.image_url || fallbackAvatar}
//         alt={user.name}
//         style={{
//           width: "100%",
//           height: "100%",
//           objectFit: "cover",
//         }}
//       />

//       {/* Online Dot */}
//       <div
//         style={{
//           position: "absolute",
//           bottom: 2,
//           right: 2,
//           width: 10,
//           height: 10,
//           borderRadius: "50%",
//           background: "#22C55E",
//           border: "2px solid white",
//         }}
//       />
//     </div>
//   );
// };

/* ------------------------------ Dropdown ------------------------------ */

const Dropdown: React.FC<DropdownProps> = ({
  value,
  options,
  onChange,
  placeholder,
  isMobile,
}) => {
  return (
    <select
      value={value}
      onChange={(e) => onChange(e.target.value)}
      style={{
        padding: "10px 14px",
        borderRadius: 10,
        border: "1px solid #E2E8F0",
        background: "#fff",
        fontSize: 14,
        minWidth: isMobile ? "48%" : 160,
        outline: "none",
        color: "#0F172A",
        fontFamily: "inherit",
      }}
    >
      <option value="all">{placeholder}</option>

      {options.map((o) => (
        <option key={o.value} value={o.value}>
          {o.label}
        </option>
      ))}
    </select>
  );
};

/* ------------------------------ Col Popover ------------------------------ */

const ColVisPopover = ({
  visible,
  onChange,
  onClose,
}: {
  visible: Set<string>;
  onChange: (key: string) => void;
  onClose: () => void;
  isMobile?: boolean;
}) => {
  const columns = [
    "name",
    "email",
    "status",
    "location",
    "phone",
    "headline",
  ];

  return (
    <div
      style={{
        position: "absolute",
        top: 50,
        right: 0,
        background: "#fff",
        border: "1px solid #E2E8F0",
        borderRadius: 12,
        padding: 14,
        width: 220,
        zIndex: 50,
        boxShadow: "0 10px 25px rgba(0,0,0,0.08)",
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          marginBottom: 10,
        }}
      >
        <strong>Columns</strong>

        <button
          onClick={onClose}
          style={{
            border: "none",
            background: "transparent",
            cursor: "pointer",
          }}
        >
          ✕
        </button>
      </div>

      {columns.map((col) => (
        <label
          key={col}
          style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
            padding: "6px 0",
            cursor: "pointer",
          }}
        >
          <input
            type="checkbox"
            checked={visible.has(col)}
            onChange={() => onChange(col)}
          />

          <span style={{ textTransform: "capitalize" }}>{col}</span>
        </label>
      ))}
    </div>
  );
};

/* ------------------------------ Main Toolbar ------------------------------ */

export const TableToolbar: React.FC<ToolbarProps> = ({
  searchTerm,
  onSearch,

  locationFilter,
  onLocationChange,
  locationOptions,

  statusFilter,
  onStatusChange,

  userTypeFilter,
  onUserTypeChange,

  visibleCols,
  onToggleCol,

  users = [],
}) => {
  const [showColPicker, setShowColPicker] = useState(false);

  const isMobile = window.innerWidth < 768;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 18,
      }}
    >
      {/* ---------------- Top Row ---------------- */}

      <div
        style={{
          display: "flex",
          flexDirection: isMobile ? "column" : "row",
          alignItems: isMobile ? "stretch" : "center",
          justifyContent: "space-between",
          gap: 16,
        }}
      >
        {/* Search */}
        <div
          style={{
            position: "relative",
            width: isMobile ? "100%" : 320,
          }}
        >
          <svg
            width="16"
            height="16"
            viewBox="0 0 16 16"
            fill="none"
            style={{
              position: "absolute",
              left: 12,
              top: "50%",
              transform: "translateY(-50%)",
              pointerEvents: "none",
            }}
          >
            <circle
              cx="7"
              cy="7"
              r="5.5"
              stroke="#94A3B8"
              strokeWidth="1.5"
            />
            <path
              d="M11 11l2.5 2.5"
              stroke="#94A3B8"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>

          <input
            type="text"
            placeholder="Search users..."
            value={searchTerm}
            onChange={(e) => onSearch(e.target.value)}
            style={{
              padding: "11px 14px 11px 38px",
              borderRadius: 12,
              border: "1px solid #E2E8F0",
              width: "100%",
              outline: "none",
              fontSize: 14,
              background: "#fff",
              boxSizing: "border-box",
            }}
          />
        </div>

        {/* Right controls */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
            flexWrap: "wrap",
          }}
        >
          <Dropdown
            value={locationFilter}
            options={locationOptions}
            onChange={onLocationChange}
            placeholder="Location"
            isMobile={isMobile}
          />

          <Dropdown
            value={statusFilter}
            options={[
              { label: "Active", value: "active" },
              { label: "Suspended", value: "suspended" },
              { label: "Pending", value: "pending" },
            ]}
            onChange={(v) => onStatusChange(v as StatusFilter)}
            placeholder="Status"
            isMobile={isMobile}
          />

          {/* Toggle */}
          <div
            style={{
              display: "flex",
              borderRadius: 10,
              border: "1px solid #E2E8F0",
              overflow: "hidden",
              background: "#fff",
            }}
          >
            {(["clients", "bidders"] as UserTypeFilter[]).map((val) => {
              const active = userTypeFilter === val;

              return (
                <button
                  key={val}
                  onClick={() =>
                    onUserTypeChange(active ? "all" : val)
                  }
                  style={{
                    padding: "10px 18px",
                    border: "none",
                    cursor: "pointer",
                    background: active ? "#0F172A" : "#fff",
                    color: active ? "#fff" : "#64748B",
                    fontWeight: 600,
                    fontSize: 14,
                    textTransform: "capitalize",
                  }}
                >
                  {val}
                </button>
              );
            })}
          </div>

          {/* Column picker */}
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setShowColPicker((v) => !v)}
              style={{
                width: 42,
                height: 42,
                border: "1px solid #E2E8F0",
                borderRadius: 12,
                background: "#fff",
                cursor: "pointer",
              }}
            >
              ☰
            </button>

            {showColPicker && (
              <ColVisPopover
                visible={visibleCols}
                onChange={onToggleCol}
                onClose={() => setShowColPicker(false)}
              />
            )}
          </div>
        </div>
      </div>

      {/* ---------------- User Avatars Preview ---------------- */}

      {/* {users.length > 0 && (
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
            overflowX: "auto",
            paddingBottom: 4,
          }}
        >
          {users.slice(0, 8).map((user) => (
            <div
              key={user.id}
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                minWidth: 70,
                gap: 6,
              }}
            >
              <Avatar user={user} />

              <span
                style={{
                  fontSize: 12,
                  color: "#475569",
                  textAlign: "center",
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  width: "100%",
                }}
              >
                {user.first_name || "User"}
              </span>
            </div>
          ))}
        </div>
      )} */}
    </div>
  );
};
